package engine

import (
	"stuntgres/internal/engine/authorization"
	"stuntgres/internal/engine/catalog"
	"stuntgres/internal/engine/ids"
	"stuntgres/internal/sqltype"
)

func associatedArrayName(stage *CatalogStage, namespace ids.ObjectAddress, name string) string {
	return ChooseAssociatedArrayName(name, func(candidate string) bool {
		return stage.LookupName(ids.NameKey{ClassID: ids.TypeClassID, Namespace: namespace, Name: candidate}) != (ids.ObjectAddress{})
	})
}

// Only reciprocal autogenerated arrays may yield a requested creation name.
// The descriptor and its codec are copied, never mutated in an older generation.
func (e *Engine) displaceAssociatedArrayLocked(stage *CatalogStage, namespace ids.ObjectAddress, name string) (bool, error) {
	key := ids.NameKey{ClassID: ids.TypeClassID, Namespace: namespace, Name: name}
	address := stage.LookupName(key)
	if address == (ids.ObjectAddress{}) {
		return true, nil
	}
	descriptor := stage.Get(address)
	if descriptor == nil {
		descriptor = stage.Base.Get(address)
	}
	array, ok := descriptor.(*catalog.Type)
	if !ok || !array.SQLType.IsArray() {
		return false, nil
	}
	elementAddress := ids.ObjectAddress{ClassID: ids.TypeClassID, ObjectID: ids.OID(array.SQLType.Element().ID())}
	elementDescriptor := stage.Get(elementAddress)
	if elementDescriptor == nil {
		elementDescriptor = stage.Base.Get(elementAddress)
	}
	element, ok := elementDescriptor.(*catalog.Type)
	if !ok || element.Array != array.SQLType.ID() || element.SQLType != array.SQLType.Element() || element.Namespace() != namespace {
		return false, nil
	}
	revision, err := e.catalog.revisionLocked()
	if err != nil {
		return false, err
	}
	next := *array
	next.ObjectRevision = revision
	// The catalog name also owns the array's database metadata label. A plain
	// name-only copy leaves that label in the previous descriptor generation.
	arrayName := associatedArrayName(stage, namespace, array.Name())
	if array.SQLType.Concrete() {
		next.SQLType, err = sqltype.Array(array.SQLType.ID(), arrayName, array.SQLType.Element())
		if err != nil {
			return false, err
		}
	} else {
		next.SQLType = sqltype.LookupArray(array.SQLType.ID(), arrayName, array.SQLType.Element())
	}
	if stage.Base.Get(address) == nil {
		nextKey := catalog.DescriptorNameKey(&next)
		nextKey.Namespace = namespace
		stage.RenameStagedDescriptor(key, &next, nextKey)
		return true, e.reownStagedTypeGenerationsLocked(stage)
	}
	if err := stage.Replace(&next); err != nil {
		return false, err
	}
	return true, e.reownStagedTypeGenerationsLocked(stage)
}

func (e *Engine) stageRowTypeLocked(stage *CatalogStage, relation *catalog.Relation) error {
	if !relation.RelationKind.Stored() && relation.RelationKind != catalog.PartitionedRelation && relation.RelationKind != catalog.ViewRelation && relation.RelationKind != catalog.CompositeRelation && relation.RelationKind != catalog.ForeignRelation || relation.RowType != 0 {
		return nil
	}
	arrayID, err := e.catalog.allocateOIDLocked()
	if err != nil {
		return err
	}
	id, err := e.catalog.allocateOIDLocked()
	if err != nil {
		return err
	}
	ns := stage.Get(relation.Namespace())
	if ns == nil {
		ns = stage.Base.Get(relation.Namespace())
	}
	declaration := catalog.DependencyIdentifier(ns.Name()) + "." + catalog.DependencyIdentifier(relation.Name())
	typ, err := sqltype.Composite(sqltype.ID(id), relation.Name(), declaration, sqltype.ID(arrayID), CompositeMembers(relation))
	if err != nil {
		return err
	}
	array, err := sqltype.Array(sqltype.ID(arrayID), associatedArrayName(stage, relation.Namespace(), relation.Name()), typ)
	if err != nil {
		return err
	}
	relation.RowType = typ.ID()
	baseline := authorization.DefaultBaseline(relation.Owner, authorization.DefaultTypes, false)
	acl := baseline
	synthetic := true
	if relation.RelationKind == catalog.CompositeRelation {
		acl, synthetic = stage.creationTypeACL(relation.Owner, relation.Namespace())
	}
	if err := stage.Create(&catalog.Type{SQLType: typ, ObjectNamespace: relation.Namespace(), ObjectRevision: relation.Revision(), Owner: relation.Owner, ACL: acl, ACLSyntheticDefault: synthetic, Array: array.ID(), OwningRelation: relation.Address()}); err != nil {
		return err
	}
	return stage.Create(&catalog.Type{SQLType: array, ObjectNamespace: relation.Namespace(), ObjectRevision: relation.Revision(), Owner: relation.Owner, ACL: baseline, ACLSyntheticDefault: true, OwningRelation: relation.Address()})
}

func (stage *CatalogStage) synchronizeRowType(relation *catalog.Relation) error {
	return stageDropProvider(nil, stage, nil, nil, nil).synchronizeRowType(relation)
}

func (provider *dropProvider) synchronizeRowType(relation *catalog.Relation) error {
	if relation.RowType == 0 {
		return nil
	}
	address := ids.ObjectAddress{ClassID: ids.TypeClassID, ObjectID: ids.OID(relation.RowType)}
	row, ok := provider.inputDescriptor(address).(*catalog.Type)
	if !ok {
		return nil
	}
	if staged, ok := provider.replacement(address).(*catalog.Type); ok {
		row = staged
	}
	return synchronizeRowTypeMetadata(relation, row, provider.descriptor, provider.associatedArrayName, provider.replace)
}

// synchronizeRowTypeMetadata is the shared metadata-only cooking core. replace
// records each actual effect before the next lookup, preserving row/array name
// occupancy and provider order without constructing a catalog or stage.
func synchronizeRowTypeMetadata(relation *catalog.Relation, row *catalog.Type, descriptor func(ids.ObjectAddress) catalog.Descriptor, associatedName func(ids.ObjectAddress, string) string, replace func(catalog.Descriptor) error) error {
	same := row.Namespace() == relation.Namespace() && row.Name() == relation.Name()
	if row.SQLType.IsComposite() {
		same = same && row.SQLType.CompositeLen() == len(relation.Columns)
		if same {
			for i, column := range relation.Columns {
				member := row.SQLType.CompositeMember(i)
				if member.Attribute != relation.Attributes[i] || member.Name != column.Name || member.Usage != column.Usage {
					same = false
					break
				}
			}
		}
	}
	if same && row.Owner == relation.Owner {
		return nil
	}
	next := *row
	if row.Owner != relation.Owner {
		next.ACL = authorization.SchemaACLOwner(row.ACL, row.Owner, relation.Owner)
	}
	next.ObjectNamespace, next.Owner, next.ObjectRevision = relation.Namespace(), relation.Owner, relation.Revision()
	if same {
		// Ownership is metadata, not a new codec or composite signature.
		next.SQLType = row.SQLType
	} else if row.SQLType.IsComposite() {
		ns := descriptor(relation.Namespace())
		var err error
		next.SQLType, err = sqltype.Composite(row.SQLType.ID(), relation.Name(), catalog.DependencyIdentifier(ns.Name())+"."+catalog.DependencyIdentifier(relation.Name()), row.Array, CompositeMembers(relation))
		if err != nil {
			return err
		}
	} else {
		next.SQLType = sqltype.LookupOnly(row.SQLType.ID(), relation.Name(), row.Array)
	}
	if err := replace(&next); err != nil {
		return err
	}
	if row.Array != 0 {
		array := descriptor(ids.ObjectAddress{ClassID: ids.TypeClassID, ObjectID: ids.OID(row.Array)}).(*catalog.Type)
		copy := *array
		if array.Owner != relation.Owner {
			copy.ACL = authorization.SchemaACLOwner(array.ACL, array.Owner, relation.Owner)
		}
		copy.ObjectNamespace, copy.Owner, copy.ObjectRevision = relation.Namespace(), relation.Owner, relation.Revision()
		arrayName := array.Name()
		if row.Name() != relation.Name() {
			arrayName = associatedName(relation.Namespace(), relation.Name())
		}
		if !same {
			if next.SQLType.IsComposite() {
				var err error
				copy.SQLType, err = sqltype.Array(array.SQLType.ID(), arrayName, next.SQLType)
				if err != nil {
					return err
				}
			} else {
				copy.SQLType = sqltype.LookupArray(array.SQLType.ID(), arrayName, next.SQLType)
			}
		}
		return replace(&copy)
	}
	return nil
}
